{
  "category_edits": [
    {
      "category": "sequence_interest",
      "rationale": "Test whether pooling the two most recent observed states reduces smoothing across older interests. Retain the 0.8 current-state/0.2 pooled-state blend, padding-aware normalization, causal backbone and final-real-position readout across all four category models.",
      "edits": [
        {
          "find": "starts = (torch.arange(length, device=seq.device) - 3).clamp(min=0)",
          "replace": "starts = (torch.arange(length, device=seq.device) - 1).clamp(min=0)"
        },
        {
          "find": "\"sequence_readout\": \"causal_recent4_blend_0.2\",",
          "replace": "\"sequence_readout\": \"causal_recent2_blend_0.2\","
        },
        {
          "find": "if meta.get(\"sequence_readout\") != \"causal_recent4_blend_0.2\":",
          "replace": "if meta.get(\"sequence_readout\") != \"causal_recent2_blend_0.2\":"
        }
      ]
    }
  ],
  "change_summary": "Shorten causal readout pooling from four states to two and synchronize checkpoint metadata and embedded predictor compatibility checks."
}
